add_action( 'woocommerce_login_form_end', 'perfectpixel_toggle_register_link' );
add_action( 'woocommerce_register_form_end', 'perfectpixel_toggle_login_link' );
add_action( 'woocommerce_after_customer_login_form', 'perfectpixel_toggle_registration_script' );

function perfectpixel_toggle_register_link() {
	if ( 'yes' === get_option( 'woocommerce_enable_myaccount_registration' ) ) {
		echo '<p><a href="#" class="perfectpixel-show-register">' . esc_html( '{{show_register_text}}' ) . '</a></p>';
	}
}

function perfectpixel_toggle_login_link() {
	echo '<p><a href="#" class="perfectpixel-show-login">' . esc_html( '{{show_login_text}}' ) . '</a></p>';
}

function perfectpixel_toggle_registration_script() {
	if ( 'yes' !== get_option( 'woocommerce_enable_myaccount_registration' ) ) {
		return;
	}
	$start_with_register = ! empty( $_POST['register'] ); // Registration was submitted (e.g. with errors).
	?>
	<style>#customer_login .u-column1, #customer_login .u-column2 { float: none; width: 100%; max-width: 480px; margin: 0 auto; }</style>
	<script>
	( function ( registerFirst ) {
		var login    = document.querySelector( '#customer_login .u-column1' );
		var register = document.querySelector( '#customer_login .u-column2' );
		if ( ! login || ! register ) {
			return;
		}
		var show = function ( reg ) {
			login.style.display    = reg ? 'none' : '';
			register.style.display = reg ? '' : 'none';
		};
		document.addEventListener( 'click', function ( e ) {
			if ( e.target.closest( '.perfectpixel-show-register' ) || e.target.closest( '.perfectpixel-show-login' ) ) {
				e.preventDefault();
				show( !! e.target.closest( '.perfectpixel-show-register' ) );
			}
		} );
		show( registerFirst );
	} )( <?php echo $start_with_register ? 'true' : 'false'; ?> );
	</script>
	<?php
}
